(HERE/'guide.css').write_text('/* SPDX-FileCopyrightText: 2026 Open Science Stiftung (Open Science Foundation) */\n/* SPDX-License-Identifier: Apache-2.0 */\n'+CSS)
(HERE/'index.html').write_text('<!-- SPDX-FileCopyrightText: 2026 Open Science Stiftung (Open Science Foundation) -->\n<!-- SPDX-License-Identifier: CC-BY-4.0 AND LicenseRef-OSF-Brand-Assets AND LicenseRef-OSF-Website-Media -->\n<!doctype html><html lang="en"><head><meta charset="UTF-8"><title>Open Science Foundation | Brand guide | 10 September 2026</title><meta name="author" content="Open Science Foundation"><link rel="stylesheet" href="guide.css"></head><body>'+''.join(PAGES)+'</body></html>')
# Accessible, editable text companion. Keep section and page order explicit.
text=[]
for i,p in enumerate(PAGES,1):
 p=re.sub(r'<svg\b[\s\S]*?</svg>','',p)
 p=re.sub(r'</(p|h1|h2|h3|div|header|footer|span|a)>','\n',p)
 p=html.unescape(re.sub('<[^>]+>','',p))
 p=re.sub(r'\n\s*\n+','\n\n',p).strip()
 text.append(f'## Page {i:02}\n\n'+p)
(ROOT/'docs/brand-guide-2026-09-10-text.md').write_text('<!-- SPDX-FileCopyrightText: 2026 Open Science Stiftung (Open Science Foundation) -->\n<!-- SPDX-License-Identifier: CC-BY-4.0 -->\n\n# Open Science Foundation brand guide\n\nText companion to the 26-page visual edition dated 10 September 2026.\n\n'+ '\n\n'.join(text)+'\n')
print('Built',len(PAGES),'pages')
